const Row = React.memo(({ item, onPress }) => (
  <Pressable onPress={() => onPress(item.id)}>
    <Text>{item.title}</Text>
  </Pressable>
));

function List({ data }) {
  const [selected, setSelected] = useState(null);
  return (
    <FlatList
      data={data}
      extraData={selected}
      renderItem={({ item }) => <Row item={item} onPress={(id) => setSelected(id)} />}
    />
  );
}
